mapper.select:
SELECT m.*, sub.min_price
FROM hx_movies m
INNER JOIN (
    SELECT movie_id AS id, MIN(price) AS min_price
    FROM hx_sessions
    GROUP BY movie_id
) sub ON sub.id = m.id
WHERE m.status = #{status}
ORDER BY sub.min_price ASC
LIMIT #{limit}

mapper.update:
UPDATE hx_movies
SET title=#{title}, rating=#{rating}, duration=#{duration}, genre=#{genre},
    director=#{director}, actors=#{actors}, release_date=#{releaseDate},
    poster_url=#{posterUrl}, description=#{description}, status=#{status}, tmdb_id=#{tmdbId}
WHERE id = #{id}
